  {
    "taxonId": 56023,
    "summary": "A genus of herbaceous perennial plants, mostly native to cool temperate and subarctic Europe and Asia, with a few species native to mountains in Africa and the Americas. Most form clumps with water-resistant, often fan-shaped leaves and small, petal-free green or yellow-green flowers.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p3"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56031,
    "summary": "A genus of annual or perennial flowering vines, half of whose species are native only to California, with the group distributed across temperate and subtropical regions worldwide. They twine around supports and bear white or pink trumpet-shaped flowers.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p2"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56036,
    "summary": "A genus of perennial flowering plants native to Africa. They produce upright spikes of bright red, orange or yellow flowers above grass-like or strap-shaped leaves, and their abundant nectar attracts bees and nectar-feeding birds.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p3"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56112,
    "summary": "A genus of annual and perennial herbs native throughout the Americas, with one species also native to eastern Eurasia. Their outer florets are white, pink, blue or purple, while the centres mature from yellow or white to pinkish, reddish-purple or brown.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p6", "s1:p14"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56159,
    "summary": "A genus of evergreen perennial flowering plants and subshrubs native to temperate regions, with its greatest diversity around the Mediterranean. It occurs on rocky and waste ground.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56161,
    "summary": "A genus of perennial flowering herbs represented by native species on every continent except Antarctica, with centres of diversity in Eurasia and South America, especially the Andes. They have woody roots, hairy stems and divided, toothed leaves; dried plant material develops a strong musky smell likened to male cats.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p6"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56172,
    "summary": "A genus of flowering plants native to Europe and Asia and naturalized in New Zealand, several Pacific islands, and much of the Americas. One member, Leonurus japonicus, is among the fundamental herbs of traditional Chinese medicine.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p2"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56207,
    "summary": "A genus of evergreen shrubs and small trees native to eastern Asia, from the eastern Himalayas through China and Korea to Japan. They have glossy, leathery, toothed leaves, separate male and female plants, small purplish-brown flowers and red fruits.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p3", "s1:p4"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56327,
    "summary": "A phylum of non-vascular land plants naturally distributed almost worldwide, generally in damp or humid places. Their flat green body is the long-lived dominant stage, while a slender horn-like spore-producing structure rises from it.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p3", "s2:p3"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 56328,
    "summary": "A class of hornworts comprising the phylum's species except those in Leiosporoceros. Young and adult plants usually have slime pores underneath, except in Notothylas, and support round colonies of Nostoc cyanobacteria; most also have a central column in the spore-producing structure.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p2"],
      "humanEdibility": []
    }
  }
]
